DO $garde$
DECLARE
    types_regles INTEGER; par_role INTEGER; sans_regle INTEGER; regles INTEGER;
BEGIN
    SELECT count(*) INTO types_regles FROM ${database.defaultSchemaName}.type_document WHERE regle_workflow_id IS NOT NULL;
    SELECT count(*) INTO par_role FROM ${database.defaultSchemaName}.regle_validateur WHERE employe_id IS NULL;
    SELECT count(*) INTO sans_regle FROM ${database.defaultSchemaName}.noeud WHERE regle_workflow_id IS NULL;
    SELECT count(*) INTO regles FROM ${database.defaultSchemaName}.regle_workflow;
    IF (types_regles + par_role + sans_regle) > 0
       AND coalesce(current_setting('ged.retour_arriere_avec_perte', true), '') <> 'oui' THEN
        RAISE EXCEPTION 'Retour arrière des règles de workflow refusé : il perdrait % règle(s) rattachée(s) à un type et % validateur(s) par rôle, et attribuerait une règle arbitraire à % nœud(s) sans règle. Rien n''a été modifié. Décision explicite requise : ged.retour_arriere_avec_perte = oui (DEPLOIEMENT.md §8).',
            types_regles, par_role, sans_regle;
    END IF;
    IF sans_regle > 0 AND regles = 0 THEN
        RAISE EXCEPTION 'Retour arrière des règles de workflow impossible : % nœud(s) sans règle et aucune règle à leur attribuer (l''ancien modèle en exige une par nœud).', sans_regle;
    END IF;
END
$garde$
